#include <stdio.h>
int sq(int x) { return x * x; }
int neg(int x) { return -x; }
void apply(int *a, int n, int (*f)(int)) {
    for (int *p = a; p < a + n; p++)
        *p = f(*p);
}
int main(void) {
    int v[4] = {1, -2, 3, -4};
    apply(v, 4, sq);
    apply(v + 2, 2, neg);
    printf("%d %d %d %d\n", v[0], v[1], *(v + 2), 3[v]);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(int argc, char *argv[]) {
    printf("argc = %d\n", argc);
    for (char **p = argv + 1; *p != NULL; p++)
        printf("%s: first %c, length %zu\n", *p, **p, strlen(*p));
    printf("argv[argc] is %s\n", argv[argc] == NULL ? "NULL" : "set");
    return 0;
}

