What is the output of the following program?

#include <stdio.h>
void stats(const int *a, int n, int *mn, int *mx) {
    *mn = *mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *mn) *mn = a[i];
        if (a[i] > *mx) *mx = a[i];
    }
}
int main(void) {
    int v[] = {4, -2, 9, 0}, lo, hi;
    stats(v, 4, &lo, &hi);
    printf("%d %d", lo, hi);
    return 0;
}

