What is the output of the following program?

#include <stdio.h>
int *largest(int *a, int n) {
    int *m = a;
    for (int i = 1; i < n; i++)
        if (a[i] > *m) m = a + i;
    return m;
}
int main(void) {
    int v[] = {3, 8, 2, 8, 5};
    int *p = largest(v, 5);
    *p = 0;
    printf("%td %d %d", p - v, v[1], v[3]);
    return 0;
}

